import java.util.*;
import java.util.stream.*;

public class Main {
    public static void printValue(long v) {
        System.out.println(v);
    }

    public static void processInput(List<Long> data) {
        long minValue = Collections.min(data);
        long maxValue = Collections.max(data);
        printValue(minValue + (maxValue - minValue) / 2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        List<Long> vals = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            vals.add(scanner.nextLong());
        }
        processInput(vals);
        scanner.close();
    }
}
